package main

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

const maxImageBytes = 16 * 1024 * 1024 // 16 MiB upload cap

var (
	serviceKey    []byte
	keyMu         sync.RWMutex
	shuttingDown  int32
	pendingJobs   sync.WaitGroup
	authCache     map[string]time.Time
	authCacheMu   sync.RWMutex
)

func init() {
	authCache = make(map[string]time.Time)
}

func loadServiceKey() error {
	keyMu.Lock()
	defer keyMu.Unlock()
	data, err := os.ReadFile("/etc/imgpipe/service.key")
	if err != nil {
		return err
	}
	serviceKey = data
	return nil
}

func verifyRequest(r *http.Request) bool {
	if atomic.LoadInt32(&shuttingDown) == 1 {
		return false
	}

	token := r.Header.Get("X-Service-Token")
	timestamp := r.Header.Get("X-Request-Time")
	signature := r.Header.Get("X-Signature")

	if token == "" || timestamp == "" || signature == "" {
		return false
	}

	// Check cache first
	authCacheMu.RLock()
	if expiry, ok := authCache[token+signature]; ok {
		authCacheMu.RUnlock()
		return time.Now().Before(expiry)
	}
	authCacheMu.RUnlock()

	// Verify timestamp freshness
	reqTime, err := time.Parse(time.RFC3339, timestamp)
	if err != nil {
		return false
	}
	if time.Since(reqTime) > 30*time.Second {
		return false
	}

	// Verify HMAC signature
	keyMu.RLock()
	currentKey := serviceKey
	keyMu.RUnlock()

	if currentKey == nil {
		return false
	}

	mac := hmac.New(sha256.New, currentKey)
	mac.Write([]byte(token + timestamp))
	expected := hex.EncodeToString(mac.Sum(nil))

	if hmac.Equal([]byte(expected), []byte(signature)) {
		authCacheMu.Lock()
		authCache[token+signature] = time.Now().Add(5 * time.Minute)
		authCacheMu.Unlock()
		return true
	}
	return false
}

func processImage(ctx context.Context, data io.Reader) ([]byte, error) {
	buf := make([]byte, 0, 1024*1024)
	tmp := make([]byte, 32*1024)
	for {
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		default:
			n, err := data.Read(tmp)
			if n > 0 {
				buf = append(buf, tmp[:n]...)
			}
			if err == io.EOF {
				return buf, nil
			}
			if err != nil {
				return nil, err
			}
		}
	}
}

func handleImageProcess(w http.ResponseWriter, r *http.Request) {
	if !verifyRequest(r) {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	pendingJobs.Add(1)
	defer pendingJobs.Done()

	ctx, cancel := context.WithTimeout(r.Context(), 30*time.Second)
	defer cancel()

	// Enforce a maximum request body size to prevent memory-exhaustion DoS.
	body := http.MaxBytesReader(w, r.Body, maxImageBytes)

	result, err := processImage(ctx, body)
	if err != nil {
		http.Error(w, "processing failed", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "image/png")
	w.Write(result)
}

func gracefulShutdown(srv *http.Server, sigCh chan os.Signal) {
	<-sigCh
	fmt.Println("Shutdown signal received...")

	atomic.StoreInt32(&shuttingDown, 1)

	// Wait for pending jobs before clearing key
	pendingJobs.Wait()

	// Clear the key material after all jobs complete
	keyMu.Lock()
	serviceKey = nil
	keyMu.Unlock()

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	srv.Shutdown(ctx)
}

func main() {
	if err := loadServiceKey(); err != nil {
		fmt.Fprintf(os.Stderr, "Failed to load service key: %v\n", err)
		os.Exit(1)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/process", handleImageProcess)
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		if atomic.LoadInt32(&shuttingDown) == 1 {
			w.WriteHeader(http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusOK)
	})

	srv := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  15 * time.Second,
		WriteTimeout: 45 * time.Second,
	}

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGTERM, syscall.SIGINT)

	go gracefulShutdown(srv, sigCh)

	fmt.Println("Image processing service starting on :8443")
	if err := srv.ListenAndServe(); err != http.ErrServerClosed {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
